/**
 * CINE-008: Endpoint Cache Classification & Policy Registry
 *
 * Classifies every API endpoint into STATIC, SEMISTATIC, or PRIVATE tiers.
 * Enforces:
 * - Zero shared caching for guest/session/private/IP-derived state
 * - Explicit TTL and bounded stale-while-revalidate (SWR) windows per public tier
 * - Explicit Cache-Control and Vary headers per response
 */

export type EndpointCacheTier = "STATIC" | "SEMISTATIC" | "PRIVATE";
export type CacheScope = "public" | "private";

export interface EndpointCachePolicy {
  readonly id: string;
  readonly routePattern: string;
  readonly tier: EndpointCacheTier;
  readonly scope: CacheScope;
  readonly ttlMs: number;
  readonly staleWhileRevalidateMs: number;
  readonly maxEntries: number;
  readonly cacheControlHeader: string;
  readonly varyHeader?: string;
  readonly keyDimensions: readonly string[];
  readonly description: string;
}

const STATIC_CACHE_CONTROL = "public, max-age=3600, s-maxage=86400, stale-while-revalidate=3600";
const DISCOVER_CACHE_CONTROL = "public, max-age=60, s-maxage=300, stale-while-revalidate=600";
const SEARCH_CACHE_CONTROL = "public, max-age=60, s-maxage=300, stale-while-revalidate=300";
const KEYWORD_CACHE_CONTROL = "public, max-age=120, s-maxage=600, stale-while-revalidate=600";
const DETAIL_CACHE_CONTROL = "public, max-age=300, s-maxage=1800, stale-while-revalidate=1800";
const DYNAMIC_LIST_CACHE_CONTROL = "public, max-age=120, s-maxage=600, stale-while-revalidate=600";
const YOUTUBE_CACHE_CONTROL = "public, max-age=600, s-maxage=3600, stale-while-revalidate=1800";
const PRIVATE_NO_STORE_CONTROL = "private, no-store, no-cache, must-revalidate";

